using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.USR.Parentescos{    [SwaggerSchema("Modelo de lectura de un Parentesco")]    [GraphQLDescription("Objeto que representa un Parentesco existente.")]    public class clReadParentescos    {        [SwaggerSchema("Identificador único del Parentesco")]        [GraphQLDescription("Identificador único del Parentesco")]        public int? ParentescoID { get; set; }        [SwaggerSchema("Parentesco")]        [GraphQLDescription("Parentesco")]        public string? Parentesco { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Parentesco")]    [GraphQLDescription("Input para crear un Parentesco.")]    public class clCreateParentescos    {        [GraphQLNonNullType] [SwaggerSchema("Parentesco")]        [GraphQLDescription("Parentesco")]        public string Parentesco { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Parentesco")]    [GraphQLDescription("Input para actualizar parcialmente un Parentesco.")]    public class clUpdateParentescos    {        [SwaggerSchema("Identificador único del Parentesco")]        [GraphQLDescription("Identificador único del Parentesco")]        public int? ParentescoID { get; set; }        [SwaggerSchema("Parentesco")]        [GraphQLDescription("Parentesco")]        public string? Parentesco { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}